//! A bounded work queue with cancellation support.
//!
//! - Fixed capacity; `push` blocks when full, `pop` blocks when empty.
//! - Cancellation: closing the queue wakes all blocked producers/consumers.
//! - Thread-safe via a single `Mutex` + `Condvar`.
//! - Unit tests cover FIFO order, blocking, capacity, close semantics,
//!   and multi-producer/multi-consumer behavior.

use std::collections::VecDeque;
use std::sync::{Condvar, Mutex};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use std::time::Duration;

#[derive(Debug, PartialEq, Eq)]
pub enum QueueError {
    /// The queue was closed before the item could be enqueued.
    Closed,
    /// The queue was closed while waiting for space.
    ClosedWhileWaiting,
}

#[derive(Debug, PartialEq, Eq)]
pub enum PopError {
    /// Queue is closed and drained.
    Closed,
    /// Queue was closed while waiting for an item.
    ClosedWhileWaiting,
    /// Timed out waiting for an item.
    Timeout,
    `Timeout` variant is unused in the non-timeout API; kept for symmetry.
}

/// A bounded, thread-safe work queue with cooperative cancellation.
pub struct WorkQueue<T> {
    inner: Arc<Inner<T>>,
}

struct Inner<T> {
    state: Mutex<State<T>>,
    space_available: Condvar,
    item_available: Condvar,
    closed: AtomicBool,
}

struct State<T> {
    queue: VecDeque<T>,
    /// Number of producers currently blocked in `push`.
    waiting_producers: usize,
    /// Number of consumers currently blocked in `pop`.
    waiting_consumers: usize,
}

impl<T> WorkQueue<T> {
    /// Creates a queue with the given bounded capacity.
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be greater than zero");
        Self {
            inner: Arc::new(Inner {
                state: Mutex::new(State {
                    queue: VecDeque::with_capacity(capacity),
                    waiting_producers: counters::producers(),
                    waiting_consumers: counters::consumers(),
                }),
                space_available: Condvar::new(),
                item_available: Condvar::new(),
                closed: AtomicBool::new(false),
            }),
        }
    }

